<script setup lang="ts">
import {computed,ref,onMounted,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import AccountDelete from '../components/AccountDelete.vue';import PageHeading from '../components/PageHeading.vue';import {api} from '../api';import {useUI,useData} from '../store';import {accountName,date} from '../domain';import type {Alias} from '../types';
const ui=useUI(),data=useData(),route=useRoute(),router=useRouter(),rows=ref<Alias[]>([]),loading=ref(false),error=ref('');const deleteTarget=ref<Alias|null>(null);const hidden=computed({get:()=>route.query.hidden==='1',set:v=>{void router.replace({query:{...route.query,hidden:v?'1':undefined}});}});const page=ref(1);
// 状态保留在路由中，刷新与返回页面时沿用筛选，旧账号缺省按未知处理。
const statusFilter=computed({get:()=>['normal','unknown','restricted'].includes(String(route.query.status))?String(route.query.status):'all',set:value=>{void router.replace({query:{...route.query,status:value==='all'?undefined:value}});}});
const filteredRows=computed(()=>rows.value.filter(row=>statusFilter.value==='all'||(row.account_status??'unknown')===statusFilter.value));
watch(statusFilter,()=>{page.value=1;});
watch(()=>filteredRows.value.length,total=>{page.value=Math.min(page.value,Math.max(1,Math.ceil(total/10)));});
/** 功能：读取历史映射，失败保留上次列表；参数：无；返回值：异步完成。 */
async function load(){if(loading.value)return;loading.value=true;error.value='';try{rows.value=(await api.aliases(hidden.value)).accounts;page.value=Math.min(page.value,Math.max(1,Math.ceil(rows.value.length/10)));}catch(e){error.value=e instanceof Error?e.message:'读取失败';}finally{loading.value=false;}}
/** 功能：管理授权后打开账号永久删除预览；参数：账号行；返回值：无。 */
function openDelete(row:Alias){if(!ui.authorized){ui.authOpen=true;return;}deleteTarget.value=row;}
watch(hidden,()=>{page.value=1;void load();});watch(()=>data.fetchedAt,()=>void load());onMounted(load);
</script><template><PageHeading title="账号映射" note="名称跟随账号UUID，不跟随电脑；隐藏保留历史和映射。" eyebrow="IDENTITY MAPPING"><el-button type="primary" @click="ui.open({kind:'alias'})">新增映射</el-button></PageHeading><div class="toolbar"><el-radio-group v-model="statusFilter" aria-label="账号状态筛选"><el-radio-button value="all">全部</el-radio-button><el-radio-button value="normal">正常</el-radio-button><el-radio-button value="unknown">未知</el-radio-button><el-radio-button value="restricted">受限</el-radio-button></el-radio-group><el-switch v-model="hidden" active-text="包含隐藏账号"/><el-button :loading="loading" @click="load">重新加载</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon class="global-alert"/><section class="table-panel" v-loading="loading"><el-table :data="filteredRows.slice((page-1)*10,page*10)" empty-text="暂无账号映射"><el-table-column label="账号" min-width="200"><template #default="{row}"><strong>{{accountName(row)}}</strong><small class="cell-sub">{{row.plan_type||'套餐未知'}} · {{row.hidden?'隐藏':'显示中'}}</small></template></el-table-column><el-table-column prop="account_id" label="账号ID" min-width="270"/><el-table-column label="账号状态" width="120"><template #default="{row}">{{row.account_status==='normal'?'正常':row.account_status==='restricted'?'受限':'未知'}}</template></el-table-column><el-table-column prop="owner" label="负责人" width="120"/><el-table-column label="在用设备" width="120"><template #default="{row}">{{data.active.filter(machine=>machine.account_id===row.account_id).length}} 台</template></el-table-column><el-table-column label="最近上报" min-width="170"><template #default="{row}">{{date(row.last_reported_at)}}</template></el-table-column><el-table-column label="操作" min-width="300"><template #default="{row}"><el-button link @click="ui.open({kind:'account-status',target:{...row}})">状态</el-button><el-button link type="primary" @click="ui.open({kind:'alias',target:{...row}})">编辑</el-button><el-button link @click="ui.open({kind:'hide',target:{...row}})">{{row.hidden?'恢复显示':'隐藏'}}</el-button><el-button v-if="row.display_name" link type="danger" @click="ui.open({kind:'remove-alias',target:{...row}})">删除映射</el-button><el-button link type="danger" @click="openDelete(row)">删除账号记录</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="10" :total="filteredRows.length" layout="total,prev,pager,next" class="pager"/></section><AccountDelete :target="deleteTarget" @close="deleteTarget=null" @deleted="load"/></template>
